SELECT 
FROM ENTERPRISE_INFO


        AND ENTERPRISE_NAME LIKE CONCAT('%', #{query.enterpriseName}, '%')


        AND CREDIT_CODE LIKE CONCAT('%', #{query.creditCode}, '%')


        AND ENTERPRISE_TYPE = #{query.enterpriseType}


        AND SUPERVISION_LEVEL = #{query.supervisionLevel}


        AND ENTERPRISE_STATUS = #{query.enterpriseStatus}


        AND LISTING_STATUS = #{query.listingStatus}


        AND LEGAL_REPRESENTATIVE LIKE CONCAT('%', #{query.legalRepresentative}, '%')


        AND INDUSTRY_CODE = #{query.industryCode}


        AND REGION_CODE = #{query.regionCode}


        AND PARENT_ENTERPRISE_ID = #{query.parentEnterpriseId}


        AND ESTABLISH_DATE >= #{query.establishStartDate}


        AND ESTABLISH_DATE <= #{query.establishEndDate}


        AND CREATE_TIME >= #{query.createStartTime}


        AND CREATE_TIME <= #{query.createEndTime}


        AND REGISTERED_CAPITAL >= #{query.minRegisteredCapital}


        AND REGISTERED_CAPITAL <= #{query.maxRegisteredCapital}



    ORDER BY ${query.orderBy}

        ${query.orderDirection}



    ORDER BY CREATE_TIME DESC

